#!/usr/bin/env node
/**
 * Writes ios-shell/app-url.js from APP_URL in capacitor.config.ts, so the
 * bundled offline screen's "Try again" button loads the same site as the app.
 * capacitor.config.ts stays the one place the URL is set.
 *
 * Run by `npm run ios:sync` before `cap sync ios`. The generated file is
 * committed too; src/__tests__/native-config.test.ts fails if it drifts.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const config = readFileSync(resolve(root, "capacitor.config.ts"), "utf8");
const match = config.match(/const APP_URL = "(https:\/\/[^"\s]+)";/);
if (!match) {
  console.error('ios-shell-config: could not find `const APP_URL = "https://...";` in capacitor.config.ts');
  process.exit(1);
}

const out = resolve(root, "ios-shell", "app-url.js");
writeFileSync(
  out,
  `// Generated by scripts/ios-shell-config.mjs from capacitor.config.ts. Do not edit.\nwindow.FINDAMINE_APP_URL = ${JSON.stringify(match[1])};\n`
);
console.log(`ios-shell-config: ${out} -> ${match[1]}`);
